/**
 * This node replaces the Aggregate node and your individual scraper.
 * It waits for all pages (Home, About, Services) to finish, 
 * cleans them, and merges them into ONE item for the AI.
 */

const allItems = $input.all();
let combinedText = "";
let totalWordCount = 0;
let pageCount = 0;

// 1. Helper function to strip HTML tags and scripts
function cleanHtml(str) {
    if (!str) return "";

    return str
        .replace(/<script\b[^>]*>([\s\S]*?)<\/script>/gmi, "") // Remove scripts
        .replace(/<style\b[^>]*>([\s\S]*?)<\/style>/gmi, "")   // Remove CSS
        .replace(/<[^>]*>?/gm, ' ')                            // Strip all HTML tags
        .replace(/\s+/g, ' ')                                  // Collapse whitespace
        .trim();
}

// 2. Loop through every item (Home, About, Services)
allItems.forEach((item) => {
    // Check common n8n body fields
    let html = item.json.body || item.json.data || "";
    let url = item.json.url || "Unknown Page";

    let cleaned = cleanHtml(html);

    if (cleaned.length > 10) {
        // Add a header for each page so the AI knows the source
        combinedText += `\n--- START OF PAGE: ${url} ---\n${cleaned.substring(0, 3500)}\n`;
        totalWordCount += cleaned.split(' ').length;
        pageCount++;
    }
});

// 3. Return as a single item
return {
    all_pages_content: combinedText || "No content found on any page",
    totalWordCount: totalWordCount,
    pageCount: pageCount,
    executionDate: new Date().toISOString()
};

// 1. Get links from the HTML Extractor and the original URL from the first HTTP Node
const links = $input.first().json.links || [];
const homeUrl = $node["HTTP Request"].json.url; 

const targets = ['about', 'service'];
const uniqueUrls = new Set();

// Always keep the homepage in the list
uniqueUrls.add(homeUrl);

// 2. Filter the found links
links.forEach(link => {
  if (link && targets.some(t => link.toLowerCase().includes(t))) {
    try {
      // This converts "/about" to "https://example.com/about"
      const fullUrl = new URL(link, homeUrl).href;
      uniqueUrls.add(fullUrl);
    } catch (e) {
      // Skip broken or non-web links (like mailto:)
    }
  }
});

// 3. Output as separate items so the next HTTP node loops through them
return Array.from(uniqueUrls).map(url => ({ json: { url: url } }));

